examples:
// Basic usage with previous and next items
<ContentNavigation
  previous={{ title: 'Previous Article', slug: 'previous-article' }}
  next={{ title: 'Next Article', slug: 'next-article' }}
  basePath="/journal"
/>

// With back link to index page
<ContentNavigation
  previous={previousPost}
  next={nextPost}
  basePath="/journal"
  backLinkText="Back to Journal"
/>

// Desktop only navigation
<ContentNavigation
  previous={previousPost}
  next={nextPost}
  basePath="/work"
  displayMode="desktop-only"
/>

// Mobile only with custom position
<ContentNavigation
  previous={previousPost}
  next={nextPost}
  basePath="/journal"
  displayMode="mobile-only"
  mobilePosition="top"
/>

// With custom delay and text truncation
<ContentNavigation
  previous={previousPost}
  next={nextPost}
  basePath="/journal"
  delayMs={800}
  truncateLength={25}
/>
